using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Topstar.Application.Disputes;
namespace Topstar.Web.Pages.Admin;[Authorize(Roles="Admin")]public sealed class DisputesModel(IDisputeService service):PageModel{
 public Topstar.Application.Common.ListWindow Window { get; private set; } = new();
[BindProperty(SupportsGet=true)]public string? Status{get;set;}public IReadOnlyList<DisputeCaseItem> Cases{get;private set;}=[];[TempData]public string? Message{get;set;}[TempData]public bool MessageSuccess{get;set;}public async Task OnGetAsync(CancellationToken ct) { Window = Topstar.Web.Features.Common.Paging.ListWindowRequest.Read(Request,"adminDisputeList"); Cases=await service.GetAdminQueueAsync(Status,ct, Window); }public async Task<IActionResult> OnPostTakeAsync(Guid id,CancellationToken ct)=>Done(await service.TakeAsync(UserId(),id,ct));public async Task<IActionResult> OnPostDecideAsync(Guid id,string decision,string resolution,CancellationToken ct)=>Done(await service.DecideAsync(UserId(),id,decision,resolution,ct));private IActionResult Done(DisputeResult x){Message=x.Message;MessageSuccess=x.Success;return RedirectToPage(new{status=Status});}private Guid UserId()=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);}
